class Bowl:
    def __init__(self, n):
        self.n = n

    def __str__(self):
        return f"装了 {self.n} 条小鱼干"

    def __add__(self, other):
        return Bowl(self.n + other.n)

print(Bowl(3) + Bowl(4))

class Bowl:
    def __init__(self, n):
        self.n = n

    def __len__(self):
        return self.n

    def __eq__(self, other):
        return self.n == other.n

print(len(Bowl(5)))
print(Bowl(5) == Bowl(5))
